	/**
	 * Feed the all-time community "Global Claims" total. Zero (local mode, or before the first poll)
	 * hides the section; a higher number animates the counter up to it. The first real value snaps, so
	 * we don't count up from zero across millions on login.
	 */
	void setGlobalClaims(long serverTotal)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (serverTotal <= 0)
			{
				globalHasData = false;
				applyGlobalVisibility();
				return;
			}
			globalHasData = true;
			applyGlobalVisibility();
			if (revealCommunityPending)
			{
				// Coming online: fade the whole section in, timed to land after the battles cascade.
				revealCommunityPending = false;
				scheduleReveal(globalBox, Math.max(revealCommunityAt, System.currentTimeMillis()));
			}
			if (globalTarget <= 0)
			{
				// First real total: snap, so we don't count up from zero across millions on login.
				globalShown = serverTotal;
				globalTarget = serverTotal;
				showCount(serverTotal);
				return;
			}
			// The server total is authoritative, but our optimistic local ticks can run ahead of it
			// between polls, so only ever animate UP to it - never jump the counter backward.
			if (serverTotal > globalTarget)
			{
				globalTarget = serverTotal;
				startCountUp();
			}
		});
	}

	/**
	 * One tile the local player just claimed: tick the counter up right away for instant feedback. The
	 * periodic server total ({@link #setGlobalClaims}) then folds in everyone else's with a bigger
	 * count-up. No-op until the first server total has arrived, so it only counts in server mode.
	 */
	void addLocalClaim()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (globalTarget <= 0)
			{
				return; // no real total yet (local mode, or before the first poll)
			}
			globalTarget += 1;
			startCountUp();
		});
	}

	/** Eases the displayed number up to the latest target - bigger jumps first, settling in. */
	private void startCountUp()
	{
		if (globalTimer != null && globalTimer.isRunning())
		{
			return; // already animating; it reads globalTarget each tick, so it chases the new value
		}
		globalTimer = new Timer(40, e ->
		{
			long diff = globalTarget - globalShown;
			if (diff <= 0)
			{
				globalShown = globalTarget;
				showCount(globalShown);
				globalTimer.stop();
				return;
			}
			globalShown += Math.max(1, diff / 8);
			if (globalShown > globalTarget)
			{
				globalShown = globalTarget;
			}
			showCount(globalShown);
		});
		globalTimer.start();
	}

	private static String fmt(long v)
	{
		return String.format("%,d", v);
	}

	/** Set the community count text and color it by tier, so the number visibly climbs the ranks as the
	 * community total grows (white -&gt; gold -&gt; orange -&gt; green -&gt; cyan -&gt; purple). */
	private void showCount(long v)
	{
		globalCount.setText(fmt(v));
		globalCount.setForeground(colorForClaims(v));
	}

	/** Tiered color for the community counter, loot-beam style: a bigger total climbs to a rarer color.
	 * Thresholds and colors are easy to retune. */
	private static Color colorForClaims(long n)
	{
		if (n >= 100_000_000L)
		{
			return new Color(0xB84BFF); // 100M+  purple
		}
		if (n >= 50_000_000L)
		{
			return new Color(0x33D6EB); // 50M+   cyan
		}
		if (n >= 10_000_000L)
		{
			return new Color(0x4BE04B); // 10M+   green
		}
		if (n >= 1_000_000L)
		{
			return new Color(0xFF7A33); // 1M+    orange
		}
		if (n >= 100_000L)
		{
			return new Color(0xEBC733); // 100k+  gold
		}
		return Color.WHITE;             // < 100k white
	}

	/** A panel that can be faded in (alpha 0 -&gt; 1), used for the coming-online reveal cascade. Stays
	 *  non-opaque so Swing still clears the area behind it (an opaque component painted at partial alpha leaves
	 *  stale pixels). A zebra/card fill is drawn as CONTENT in paintComponent instead of as an opaque background,
	 *  so it composites correctly during the fade. */
	private static final class FadePanel extends JPanel
	{
		private float alpha = 1f;
		private Color fill; // optional background fill painted as content (null = transparent)

		FadePanel()
		{
			setOpaque(false); // non-opaque so the fade composites cleanly over the parent
		}

		FadePanel(java.awt.LayoutManager layout)
		{
			super(layout);
			setOpaque(false); // non-opaque so the fade composites cleanly over the parent
		}

		void setFill(Color c)
		{
			fill = c;
			repaint();
		}

		void setAlpha(float a)
		{
			alpha = Math.max(0f, Math.min(1f, a));
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			if (fill != null)
			{
				g.setColor(fill);
				g.fillRect(0, 0, getWidth(), getHeight());
			}
			super.paintComponent(g);
		}

		@Override
		public void paint(Graphics g)
		{
			if (alpha >= 1f)
			{
				super.paint(g);
				return;
			}
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			super.paint(g2);
			g2.dispose();
		}
	}

	/** Fade a panel in starting at {@code startMs} (epoch ms), driven by one shared reveal timer. */
	private void scheduleReveal(FadePanel c, long startMs)
	{
		c.setAlpha(0f);
		reveals.put(c, startMs);
		if (revealTimer == null)
		{
			revealTimer = new Timer(25, e -> tickReveals());
		}
		if (!revealTimer.isRunning())
		{
			revealTimer.start();
		}
	}

	private void tickReveals()
	{
		long now = System.currentTimeMillis();
		Iterator<Map.Entry<FadePanel, Long>> it = reveals.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<FadePanel, Long> e = it.next();
			long start = e.getValue();
			float a = now <= start ? 0f : Math.min(1f, (now - start) / (float) REVEAL_FADE_MS);
			e.getKey().setAlpha(a);
			if (a >= 1f)
			{
				it.remove();
			}
		}
		if (reveals.isEmpty())
		{
			revealTimer.stop();
		}
	}

	/**
	 * @param claims          every claimed tile in the current world
	 * @param world           the world these claims belong to
	 * @param totalTiles      denominator for the GE-share percentage
	 * @param committedLeader the current owner per the sticky/debounced rule (matches the boundary);
	 *                        it wins ties so the panel's #1 and headline never disagree with the wall
	 * @param myClan          the player's own clan, or null/empty if they're not in one (shows a hint)
	 */
	void update(Collection<ClanTurfPoint> claims, int world, int totalTiles, String committedLeader,
			String myClan, ClanTurfBattle currentBattle, ClanTurfStore.ConnectionStatus status,
			boolean clanHintDue, Map<String, Long> perClanTiles)
	{
		final Map<String, Long> perClanTilesFinal =
				perClanTiles == null ? java.util.Collections.emptyMap() : perClanTiles;
		Map<String, Long> counts = claims.stream()
				.collect(Collectors.groupingBy(ClanTurfPoint::getClanName, Collectors.counting()));

		// Rank by tiles held: whoever has the most is #1, so out-tiling a rival puts you on top even
		// before the debounced owner flip catches up. A tie is broken in the committed owner's favor
		// (matches the boundary), then by the sticky base order so tied clans don't shuffle. Per world.
		if (world != boardOrderWorld)
		{
			boardOrderWorld = world;
			boardOrder.clear();
		}
		List<String> base = stickyBase(counts.keySet(), counts);
		base.sort((a, b) ->
		{
			int byTiles = Long.compare(counts.get(b), counts.get(a));
			if (byTiles != 0)
			{
				return byTiles; // most tiles first
			}
			boolean ac = a.equalsIgnoreCase(committedLeader);
			boolean bc = b.equalsIgnoreCase(committedLeader);
			if (ac != bc)
			{
				return ac ? -1 : 1; // tie: committed owner holds #1
			}
			return 0; // full tie: keep the stable sticky base order
		});
		boardOrder.clear();
		boardOrder.addAll(base);
		List<Entry> ordered = base.stream()
				.map(clan -> new Entry(clan, ClanTurfColors.forClan(clan), counts.get(clan)))
				.collect(Collectors.toList());

		long claimed = ordered.stream().mapToLong(e -> e.tiles).sum();

		// Only show the "join a clan" hint once we're confident: clan-less AND the channel has had time
		// to load. Otherwise it flashes at clan members during the login/connect wait before their clan
		// channel arrives.
		boolean clanless = (myClan == null || myClan.trim().isEmpty()) && clanHintDue;

		SwingUtilities.invokeLater(() ->
		{
			if (!signedIn)
			{
				setSignedIn(true); // first live update after login: reveal battles + alliance
			}
			if (revealBarsPending)
			{
				// Coming online: the bars were blanked on the switch; keep them blank through the hold window
				// (not just while empty) so they never render in a placeholder color and recolor once the
				// alliance colors land. Release when the hold times out (colors load within ~1s of the switch).
				if (System.currentTimeMillis() < revealHoldUntil)
				{
					return;
				}
				revealBarsPending = false;
			}

			header.setText("Clan Turf - World " + world);
			clanHint.setVisible(clanless);

			if (ordered.isEmpty())
			{
				if (currentBattle != null && currentBattle.getOwner() != null)
				{
					// Away from the GE the local bars are gated off, but the always-on battles data
					// still knows who holds your world - keep the headline live.
					Color oc = ClanTurfColors.forClan(currentBattle.getOwner());
					String ohex = String.format("%02x%02x%02x",
							oc.getRed(), oc.getGreen(), oc.getBlue());
					headlineOwner = "GE owners: <b style='color:#" + ohex + "'>"
							+ escape(currentBattle.getOwner()) + "</b>";
					stakeClaimed = currentBattle.getOwnerTiles();
					stakeTotal = currentBattle.getTotalTiles();
					renderHeadline();
				}
				else if (status == ClanTurfStore.ConnectionStatus.CONNECTING)
				{
					// Cold start: the server hasn't answered yet, so don't imply the GE is empty.
					headlineOwner = null;
					headline.setText("Connecting to the sync server…");
				}
				else if (status == ClanTurfStore.ConnectionStatus.OFFLINE)
				{
					headlineOwner = null;
					headline.setText("Sync server unreachable - retrying.");
				}
				else
				{
					headlineOwner = null;
					headline.setText("No tiles claimed yet - walk the GE.");
				}
			}
			else
			{
				Entry lead = ordered.get(0);
				String hex = String.format("%02x%02x%02x",
						lead.color.getRed(), lead.color.getGreen(), lead.color.getBlue());
				headlineOwner = "GE owners: <b style='color:#" + hex + "'>" + escape(lead.clan) + "</b>";
				stakeClaimed = claimed;
				stakeTotal = totalTiles;
				renderHeadline();
			}

			allianceTileCounts = perClanTilesFinal; // per-clan breakdown for the expanded-alliance drawer
			board.setData(ordered, totalTiles, myClan);
		});
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * Rebuilds the Active battles list (server mode only; empty otherwise).
	 *
	 * @param myClan       the player's own clan, so a world it owns shows "Defend" instead of "Invade"
	 * @param currentWorld the world you're on, so its row drops the button and shows larger
	 */
	void updateBattles(List<ClanTurfBattle> battles, String myClan, int currentWorld)
	{
		List<ClanTurfBattle> list = battles != null ? new ArrayList<>(battles) : new ArrayList<>();
		SwingUtilities.invokeLater(() ->
		{
			if (revealBattlesPending && System.currentTimeMillis() < revealHoldUntil)
			{
				// Coming online: battles were blanked on the switch; keep them blank through the hold window
				// (even though the always-on battles poll has data) so rows don't render in a placeholder
				// color and recolor once the alliance colors land, then cascade the final rows in.
				return;
			}
			// Skip the teardown/rebuild when nothing changed, so the list doesn't flash every refresh.
			// A pending reveal always rebuilds (it needs fresh rows to cascade in).
			lastBattles = list;
			lastBattlesMyClan = myClan;
			lastBattlesWorld = currentWorld;
			// Retarget the per-world tile counts and kick the count-up BEFORE the rebuild guard, so a poll that only
			// changes counts (no reorder) rolls the numbers in place instead of rebuilding the rows. My current
			// world's counts are local claims, so retargetBattles snaps them instantly (never eased).
			battleCurrentWorld = currentWorld;
			retargetBattles(list);
			startLbAnim();
			String sig = battlesSignature(list, myClan, currentWorld);
			if (!revealBattlesPending && sig.equals(lastBattlesSig))
			{
				return;
			}
			lastBattlesSig = sig;
			battlesBox.removeAll();
			battleTileLabel.clear();  // all re-registered per world in battleRow during this rebuild
			battleContested.clear();
			battleBorder.clear();
			battleRowComp.clear();
			if (list.isEmpty())
			{
				JLabel none = new JLabel("None right now.");
				none.setFont(FontManager.getRunescapeSmallFont());
				none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				none.setAlignmentX(Component.LEFT_ALIGNMENT);
				battlesBox.add(none);
			}
			else
			{
				// Cascade the rows the first time real battle rows render this session (same trigger the leaderboard
				// uses), so it reliably plays on login - not only on the offline->online transition.
				// cascadeAll = first load this session (pinned world + rest). cascadeRest = a page flip, where the
				// pinned current-world row is unchanged, so only the non-pinned rows re-cascade.
				boolean cascadeAll = !battlesCascadedOnce;
				boolean cascadeRest = battlesRecascadeRestOnly;
				battlesRecascadeRestOnly = false; // consume the one-shot page-flip flag
				revealBattlesPending = false; // consume the online-transition hold flag
				long base = System.currentTimeMillis() + REVEAL_BATTLES_DELAY;

				// Your current world pins to the top; the rest sort by the chosen column.
				ClanTurfBattle pinned = null;
				List<ClanTurfBattle> rest = new ArrayList<>();
				for (ClanTurfBattle b : list)
				{
					if (pinned == null && b.getWorld() == currentWorld)
					{
						pinned = b;
					}
					else
					{
						rest.add(b);
					}
				}
				rest.sort(battleComparator());

				int i = 0;
				if (pinned != null)
				{
					FadePanel row = battleRow(pinned, myClan, currentWorld, ROW_A);
					battlesBox.add(marginHolder(row));
					battlesBox.add(Box.createVerticalStrut(2)); // PANEL_BG gap between cards, same as the leaderboard
					if (cascadeAll) // on a page flip the pinned world is unchanged, so leave it in place
					{
						scheduleReveal(row, base + i * REVEAL_ROW_STAGGER);
						i++;
					}
				}
				if (serverOn)
				{
					battlesBox.add(battleSortHeader()); // offline has a single world - no point sorting, so hide it
				}
				// Paginate the sorted (non-pinned) worlds, BATTLE_PAGE_SIZE per page, so the list stays compact
				// even with many active worlds. The pinned current-world row above is always shown, off-page.
				int battlePages = Math.max(1, (rest.size() + BATTLE_PAGE_SIZE - 1) / BATTLE_PAGE_SIZE);
				if (battlePage >= battlePages)
				{
					battlePage = battlePages - 1;
				}
				if (battlePage < 0)
				{
					battlePage = 0;
				}
				int bFrom = battlePage * BATTLE_PAGE_SIZE;
				int bTo = Math.min(bFrom + BATTLE_PAGE_SIZE, rest.size());
				for (int j = bFrom; j < bTo; j++)
				{
					ClanTurfBattle rb = rest.get(j);
					FadePanel row = battleRow(rb, myClan, currentWorld, (j - bFrom) % 2 == 0 ? ROW_A : ROW_B);
					battlesBox.add(marginHolder(row));
					battlesBox.add(Box.createVerticalStrut(2)); // PANEL_BG gap between cards, same as the leaderboard
					if (cascadeAll || cascadeRest)
					{
						scheduleReveal(row, base + i * REVEAL_ROW_STAGGER); // top-down cascade
						i++;
					}
				}
				if (battlePages > 1)
				{
					battlesBox.add(Box.createVerticalStrut(4));
					battlesBox.add(buildPager(battlePage, battlePages, pg ->
					{
						battlePage = pg;
						lastBattlesSig = null; // force a rebuild at the new page
						battlesRecascadeRestOnly = true; // re-cascade only the new page's rows, pinned world stays put
						updateBattles(new ArrayList<>(lastBattles), lastBattlesMyClan, lastBattlesWorld);
					}));
				}
				if (cascadeAll)
				{
					// Line the community counter up to arrive just after the last rendered battle row.
					revealCommunityAt = base + (long) i * REVEAL_ROW_STAGGER + REVEAL_COMMUNITY_GAP;
				}
				battlesCascadedOnce = true; // only the first render with rows cascades; later renders are instant
			}
			battlesBox.revalidate();
			battlesBox.repaint();
		});
	}

	/**
	 * A stable fingerprint of the Active-battles content: everything that changes what the rows look
	 * like (the world you're on and your clan drive the current-world pin and Defend/Invade labels, so
	 * they're included). If two calls produce the same string, the rendered list would be identical.
	 */
	private static String battlesSignature(List<ClanTurfBattle> list, String myClan, int currentWorld)
	{
		// Structure-only: world order + owner/runner names + colors. The tile COUNTS are left out on purpose - a
		// count change rolls in via tickLbAnim, and only reorders (which change the world sequence here) rebuild.
		StringBuilder sb = new StringBuilder();
		sb.append(currentWorld).append('|').append(myClan == null ? "" : myClan).append('#');
		for (ClanTurfBattle b : list)
		{
			sb.append(b.getWorld()).append(',').append(b.getOwner()).append(',')
					.append(b.getRunnerUp()).append(',')
					// Include the clans' current colors so a recolor rebuilds the rows too.
					.append(ClanTurfColors.forClan(b.getOwner()).getRGB()).append(',')
					.append(ClanTurfColors.forClan(b.getRunnerUp()).getRGB()).append(';');
		}
		return sb.toString();
	}

	/**
	 * The sticky base order for the scoreboard: clans shown last time keep their prior relative
	 * order, and any new clans are appended (most tiles first, name as a stable tiebreak). The
	 * caller then stable-sorts this by rank, so a tie holds whoever was already ahead.
	 */
	private List<String> stickyBase(Collection<String> clans, Map<String, Long> counts)
	{
		List<String> base = new ArrayList<>();
		for (String clan : boardOrder)
		{
			if (clans.contains(clan) && !base.contains(clan))
			{
				base.add(clan);
			}
		}
		List<String> fresh = new ArrayList<>();
		for (String clan : clans)
		{
			if (!base.contains(clan))
			{
				fresh.add(clan);
			}
		}
		fresh.sort((a, b) ->
		{
			int d = Long.compare(counts.get(b), counts.get(a));
			return d != 0 ? d : a.compareTo(b);
		});
		base.addAll(fresh);
		return base;
	}

	/** Comparator for the non-pinned battle rows, per the chosen column and direction. */
	private java.util.Comparator<ClanTurfBattle> battleComparator()
	{
		if (battleSort == BattleSort.OWNER)
		{
			// Cluster same owners; direction flips the owner order, tiles stay high-to-low within a group.
			java.util.Comparator<ClanTurfBattle> byOwner = java.util.Comparator.comparing(
					(ClanTurfBattle b) -> b.getOwner() == null ? "" : b.getOwner().toLowerCase());
			if (battleSortDesc)
			{
				byOwner = byOwner.reversed();
			}
			return byOwner.thenComparing(
					java.util.Comparator.comparingInt(ClanTurfBattle::getOwnerTiles).reversed());
		}
		java.util.Comparator<ClanTurfBattle> c = battleSort == BattleSort.WORLD
				? java.util.Comparator.comparingInt(ClanTurfBattle::getWorld)
				: java.util.Comparator.comparingInt(ClanTurfBattle::getOwnerTiles);
		return battleSortDesc ? c.reversed() : c;
	}

	/** The clickable World / Owner / Tiles sort bar shown under the pinned current-world row. */
	private JPanel battleSortHeader()
	{
		// Three equal-width tab blocks (same style as All/Clan and the page numbers), so the sort control reads as
		// a row of toggles. The active column keeps a small arrow for its asc/desc direction.
		JPanel bar = tabGroup(true, sortLabel("World", BattleSort.WORLD),
				sortLabel("Owner", BattleSort.OWNER), sortLabel("Tiles", BattleSort.TILES));
		bar.setBorder(BorderFactory.createEmptyBorder(6, 7, 6, 7)); // inset + vertical gap so it reads as a control strip
		// Lock the strip height AFTER the border is added: tabGroup only capped height to TAB_H (border-less), so
		// the 6+6 border made max < preferred and BoxLayout smashed the buttons when the list was short / post-reset.
		// Pin min = max = the real preferred height so it renders identically regardless of row count or scrollbar.
		int barH = bar.getPreferredSize().height;
		bar.setMinimumSize(new Dimension(0, barH));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, barH));
		return bar;
	}

	/** Pins a component to a fixed width (used for the Active-battles world/tiles columns so header and rows
	 *  line up regardless of content). Height stays flexible so BorderLayout can stretch the cell. */
	private static void fixWidth(JComponent c, int w)
	{
		Dimension d = new Dimension(w, c.getPreferredSize().height);
		c.setPreferredSize(d);
		c.setMinimumSize(d);
		c.setMaximumSize(new Dimension(w, Integer.MAX_VALUE));
	}

	/** One sort column tab (World / Owner / Tiles) in the v9 block style; the active one keeps a small arrow for
	 *  its asc/desc direction and stays clickable so a second click flips the direction. */
	private JLabel sortLabel(String text, BattleSort key)
	{
		boolean active = battleSort == key;
		JLabel l = tabButton(text, active, () ->
		{
			if (battleSort == key)
			{
				battleSortDesc = !battleSortDesc; // same column: flip direction
			}
			else
			{
				battleSort = key;
				battleSortDesc = true; // new column: default descending
			}
			battlePage = 0; // a new sort reorders the list, so start from the first page
			lastBattlesSig = null; // force a rebuild with the new sort
			updateBattles(new ArrayList<>(lastBattles), lastBattlesMyClan, lastBattlesWorld);
		});
		if (active)
		{
			l.setIcon(new TriangleIcon(battleSortDesc ? TriangleIcon.DOWN : TriangleIcon.UP, 7));
			l.setHorizontalTextPosition(javax.swing.SwingConstants.LEFT);
			l.setIconTextGap(3);
		}
		return l;
	}

	/** The v9 vertical battle bar(s) down the left edge of a card: one bar in the owner's color for a solo-held
	 *  world, or TWO side-by-side bars (owner then challenger) for a contested one, 1px gap between. The bars form
	 *  a mini chart - each is bottom-anchored with height proportional to that clan's tiles, so the clan with more
	 *  tiles has the taller bar (the leader's reaches full height). */
	private static final class VerticalBattleBorder implements javax.swing.border.Border
	{
		private static final int BAR_W = 4;   // width of each clan's bar
		private static final int REGION = 9;  // reserved left region: two bars (4+4) + a 1px gap

		private final Color leader;
		private final Color challenger; // null = solo-held world (single bar)
		private int leaderTiles;        // mutable so the count-up can roll the bar heights with the numbers
		private int challengerTiles;
		private int totalTiles; // denominator: each bar height is that clan's share of the WHOLE GE

		VerticalBattleBorder(Color leader, Color challenger, int leaderTiles, int challengerTiles, int totalTiles)
		{
			this.leader = leader;
			this.challenger = challenger;
			this.leaderTiles = leaderTiles;
			this.challengerTiles = challengerTiles;
			this.totalTiles = totalTiles;
		}

		/** Update the bar heights to the animator's current shown values; caller repaints the row. */
		void setTiles(int leaderTiles, int challengerTiles, int totalTiles)
		{
			this.leaderTiles = leaderTiles;
			this.challengerTiles = challengerTiles;
			this.totalTiles = totalTiles;
		}

		@Override
		public void paintBorder(Component c, Graphics g, int x, int y, int w, int h)
		{
			// Each bar reflects that clan's ownership of the whole GE, so a bar is only full if they hold every tile
			// (90% ownership -> 90% bar), not just relative to the other clan.
			int denom = totalTiles > 0 ? totalTiles : Math.max(1, leaderTiles + challengerTiles);
			int leftSlot = x;
			int rightSlot = x + BAR_W + 1; // 1px gap between the two bars
			if (challenger == null)
			{
				// Solo world: a single bar, hugging the content on the right (closest to the world number).
				drawBar(g, rightSlot, y, h, barHeight(leaderTiles, denom, h), leader);
				return;
			}
			// Contested: the clan with MORE tiles sits on the RIGHT (closest to the world). Ordered by the CURRENT
			// animated counts, so the bars swap exactly when the on-screen numbers cross - not when the server
			// reports an ownership flip. setTiles() feeds this the same shown values the count-up rolls to.
			int lh = barHeight(leaderTiles, denom, h);
			int ch = barHeight(challengerTiles, denom, h);
			if (leaderTiles >= challengerTiles)
			{
				drawBar(g, rightSlot, y, h, lh, leader);
				drawBar(g, leftSlot, y, h, ch, challenger);
			}
			else
			{
				drawBar(g, rightSlot, y, h, ch, challenger);
				drawBar(g, leftSlot, y, h, lh, leader);
			}
		}

		/** A clan's bar height: its share of the whole GE, with a 2px floor so a tiny-but-nonzero holding still shows. */
		private static int barHeight(int tiles, int denom, int h)
		{
			int bh = Math.round(h * Math.min(tiles, denom) / (float) denom);
			return tiles > 0 ? Math.max(bh, 2) : bh;
		}

		private void drawBar(Graphics g, int bx, int y, int h, int bh, Color color)
		{
			g.setColor(color);
			g.fillRect(bx, y + (h - bh), BAR_W, bh); // bottom-anchored
		}

		@Override
		public java.awt.Insets getBorderInsets(Component c)
		{
			return new java.awt.Insets(0, REGION, 0, 0);
		}

		@Override
		public boolean isBorderOpaque()
		{
			return false;
		}
	}

	/** Wraps a battle card in a transparent holder that insets it 7px on each side (the guide's 14px side
	 *  margins), so PANEL_BG shows down both edges and the cards read as separate tiles. */
	private JComponent marginHolder(FadePanel card)
	{
		JPanel h = new JPanel(new BorderLayout());
		h.setOpaque(false);
		h.setAlignmentX(Component.LEFT_ALIGNMENT);
		// Cards run flush to both edges now (bars at the far left, fill to the far right).
		h.add(card, BorderLayout.CENTER);
		// Force a uniform BATTLE_CARD_H for every card (single-clan worlds included) so the list reads evenly.
		h.setPreferredSize(new Dimension(10, BATTLE_CARD_H));
		h.setMinimumSize(new Dimension(0, BATTLE_CARD_H));
		h.setMaximumSize(new Dimension(Integer.MAX_VALUE, BATTLE_CARD_H));
		return h;
	}

	private FadePanel battleRow(ClanTurfBattle b, String myClan, int currentWorld, Color cardBg)
	{
		FadePanel row = new FadePanel(new BorderLayout(6, 0));
		row.setFill(cardBg); // v9 zebra card fill, painted as content so the cascade fade stays clean
		// Vertical battle bar(s) on the left: one owner bar for a solo world, two side-by-side bars (owner +
		// challenger) for a contested one.
		Color ownerColor = ClanTurfColors.forClan(b.getOwner());
		Color runnerColor = b.getRunnerUp() != null ? ClanTurfColors.forClan(b.getRunnerUp()) : null;
		// Seed the bar from the animator's shown value (eases for server worlds, snaps for my own), and register it
		// + the row so the count-up rolls the bar heights in step with the numbers.
		long[] shownBar = battleShown.getOrDefault(b.getWorld(),
				new long[]{b.getOwnerTiles(), b.getRunnerUpTiles(), b.getTotalTiles()});
		VerticalBattleBorder vbb = new VerticalBattleBorder(ownerColor, runnerColor,
				(int) shownBar[0], (int) shownBar[1], (int) shownBar[2]);
		row.setBorder(BorderFactory.createCompoundBorder(vbb, BorderFactory.createEmptyBorder(5, 6, 5, 8)));
		battleBorder.put(b.getWorld(), vbb);
		battleRowComp.put(b.getWorld(), row);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, BATTLE_CARD_H));

		String ownerHex = hex(ownerColor);

		// Three fixed-position columns so the sort labels above always line up: world (+ [HW]) in a fixed-width
		// WEST slot, the clan name(s) flexing in the CENTER (clipped, never shifting the columns), and the tile
		// counts right-aligned in a fixed-width EAST slot. vs battles stack owner over runner-up in each column.
		// Column 1 = world number, column 2 = the home-world icon (blank unless this is a home world). Both sit in
		// one fixed-width WEST slot matching the "World" sort header, so the Owner/Tiles columns never shift.
		JPanel worldCol = new JPanel();
		worldCol.setLayout(new BoxLayout(worldCol, BoxLayout.X_AXIS));
		worldCol.setOpaque(false);
		JLabel worldNum = new JLabel("<html><nobr><b>W" + b.getWorld() + "</b></nobr></html>");
		worldNum.setFont(FontManager.getRunescapeFont());
		worldNum.setForeground(Color.WHITE);
		worldNum.setAlignmentY(Component.CENTER_ALIGNMENT);
		fixWidth(worldNum, BATTLE_WORLD_NUM_W);
		worldCol.add(worldNum);

		int hs = homeSlot(b);           // 0 = owner is home, 1 = runner-up is home, -1 = not a home world
		boolean vs = b.getRunnerUp() != null;
		JLabel hwCell = new JLabel();
		if (hs >= 0)
		{
			String homeClan = hs == 0 ? b.getOwner() : b.getRunnerUp();
			javax.swing.ImageIcon hw = homeIcon();
			if (hw != null)
			{
				hwCell.setIcon(hw);
			}
			else
			{
				// Fallback only if the icon resource is missing: the old gold [HW] text.
				hwCell.setText("<html><nobr><span style='color:#ffd700'>[HW]</span></nobr></html>");
				hwCell.setFont(FontManager.getRunescapeSmallFont());
			}
			hwCell.setToolTipText(homeClan + " home world"); // name whose home world this is
		}
		hwCell.setHorizontalAlignment(JLabel.CENTER);
		// On a vs row, align the icon to the home clan's line (owner = top, runner-up = bottom) instead of floating
		// it between the two names; single-clan rows stay centered. fixWidth leaves the cell's MAX height unbounded
		// so BoxLayout stretches it to the row height (letting TOP/BOTTOM take effect) WITHOUT raising the row's
		// own height - the preferred/min height stays the icon's, so rows don't grow.
		hwCell.setVerticalAlignment(!vs ? JLabel.CENTER : hs == 0 ? JLabel.TOP : hs == 1 ? JLabel.BOTTOM : JLabel.CENTER);
		hwCell.setAlignmentY(Component.CENTER_ALIGNMENT);
		fixWidth(hwCell, BATTLE_HW_ICON_W);
		worldCol.add(hwCell);

		fixWidth(worldCol, BATTLE_WORLD_COL_W);
		row.add(worldCol, BorderLayout.WEST);

		String ownerName = "<nobr><span style='color:#" + ownerHex + "'>"
				+ escape(clip(b.getOwner(), BATTLE_NAME_CLIP)) + "</span></nobr>";
		String ownerHtml;
		if (b.getRunnerUp() != null)
		{
			String upHex = hex(ClanTurfColors.forClan(b.getRunnerUp()));
			String upName = "<nobr><span style='color:#" + upHex + "'>"
					+ escape(clip(b.getRunnerUp(), BATTLE_NAME_CLIP)) + "</span></nobr>";
			ownerHtml = "<html><table cellpadding=0 cellspacing=0>"
					+ "<tr><td>" + ownerName + "</td></tr>"
					+ "<tr><td>" + upName + "</td></tr></table></html>";
		}
		else
		{
			// Solo world: a two-word (alliance) name breaks onto two lines; a single-word clan name stays one.
			String soloName = clip(b.getOwner(), BATTLE_NAME_CLIP);
			int sp = soloName.indexOf(' ');
			String ownerBody = ownerName;
			if (sp > 0)
			{
				ownerBody = "<nobr><span style='color:#" + ownerHex + "'>" + escape(soloName.substring(0, sp))
						+ "</span></nobr><br><nobr><span style='color:#" + ownerHex + "'>"
						+ escape(soloName.substring(sp + 1).trim()) + "</span></nobr>";
			}
			ownerHtml = "<html>" + ownerBody + "</html>";
		}
		JLabel owner = new JLabel(ownerHtml);
		owner.setFont(FontManager.getRunescapeFont());
		owner.setForeground(Color.WHITE);
		row.add(owner, BorderLayout.CENTER);

		// Tile counts seeded from the animator's shown value (eases up toward the server total via tickLbAnim), and
		// the label registered by world so the roll-in updates it in place without a rebuild.
		boolean contested = b.getRunnerUp() != null;
		long[] shownTiles = battleShown.getOrDefault(b.getWorld(),
				new long[]{b.getOwnerTiles(), b.getRunnerUpTiles()});
		JLabel tiles = new JLabel(battleTilesHtml(shownTiles[0], shownTiles[1], contested));
		tiles.setFont(FontManager.getRunescapeFont());
		tiles.setForeground(Color.WHITE);
		tiles.setHorizontalAlignment(JLabel.RIGHT);
		fixWidth(tiles, BATTLE_TILES_COL_W);
		row.add(tiles, BorderLayout.EAST);
		battleTileLabel.put(b.getWorld(), tiles);
		battleContested.put(b.getWorld(), contested);
		return row;
	}

	/** The custom home-world icon for the Active-battles HW column, loaded once and scaled. Null if the resource
	 *  is missing or unreadable (rows then fall back to the gold [HW] text). */
	private javax.swing.ImageIcon homeIcon()
	{
		if (!hwIconLoaded)
		{
			hwIconLoaded = true;
			try
			{
				BufferedImage img = ImageUtil.loadImageResource(ClanTurfPanel.class, "homeworld_icon.png");
				if (img != null)
				{
					hwIconCache = new javax.swing.ImageIcon(
							ImageUtil.resizeImage(img, BATTLE_HW_ICON_PX, BATTLE_HW_ICON_PX));
				}
			}
			catch (RuntimeException ignored)
			{
				// resource missing or unreadable - leave null; battle rows fall back to the [HW] text
			}
		}
		return hwIconCache;
	}

	/** Which participant this battle's world is the home world of: 0 = owner, 1 = runner-up, -1 = neither.
	 *  A world is one alliance's home, so at most one side matches; the home-world icon names and aligns to it. */
	private int homeSlot(ClanTurfBattle b)
	{
		if (homeWorldLookup == null || b.getWorld() <= 0)
		{
			return -1;
		}
		if (b.getOwner() != null && homeWorldLookup.applyAsInt(b.getOwner()) == b.getWorld())
		{
			return 0;
		}
		if (b.getRunnerUp() != null && homeWorldLookup.applyAsInt(b.getRunnerUp()) == b.getWorld())
		{
			return 1;
		}
		return -1;
	}

	private static String hex(Color c)
	{
		return String.format("%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}


	/** Shorten a clan/alliance name with a trailing ellipsis so an Active-battles row can't overflow the
	 *  panel and clip. The scoreboard drawer and world map still show the full name. */
	private static String clip(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		return s.length() <= max ? s : s.substring(0, Math.max(1, max - 1)).trim() + "…";
	}

	/** One clan's standing: name, color, tiles held. */
	private static final class Entry
	{
		final String clan;
		final Color color;
		final long tiles;

		Entry(String clan, Color color, long tiles)
		{
			this.clan = clan;
			this.color = color;
			this.tiles = tiles;
		}
	}

	/** Live animation state for one clan's row: displayed values ease toward the targets. */
	private static final class Row
	{
		final String clan;
		Color color;
		double tiles;        // displayed count (eases toward targetTiles)
		double targetTiles;
		double y;            // displayed top-of-row pixel (eases toward targetY)
		double targetY;
		int rank;            // target rank (1-based), snapped
		int icon;            // alliance symbol sprite id for this row (0 = not an alliance, no icon)
		boolean leaving;     // dropped out of the standings, animating out then removed
		double alpha = 1.0;  // row opacity; eases to 0 while leaving so it fades out, not cuts

		Row(String clan, Color color, double tiles, double y)
		{
			this.clan = clan;
			this.color = color;
			this.tiles = tiles;
			this.y = y;
		}
	}

	/**
	 * Opens the RuneLite color wheel for a clan (from clicking its scoreboard bar), seeded with that
	 * clan's current color. On close the chosen color goes to the plugin, which persists it as your own
	 * color or into the shared clan color list. Local only - nobody else sees your palette.
	 */
	private void openColorPicker(String clan)
	{
		if (clan == null || clan.isEmpty() || colorPickerManager == null)
		{
			return;
		}
		Window parent = SwingUtilities.getWindowAncestor(this);
		RuneliteColorPicker picker = colorPickerManager.create(
				parent, ClanTurfColors.forClan(clan), "Color for " + clan, true);
		placeNearPanel(picker);
		picker.setOnClose(c -> onClanColorChosen.accept(clan, c));
		picker.setVisible(true);
	}

