	/** Show the Community Claims section per whether there's data and whether it's collapsed. The counter
	 *  itself always stays visible (with data); collapsing only hides the intro and thank-you lines above
	 *  and below it, so the number slides up under the header and back down when reopened. */
	private void applyGlobalVisibility()
	{
		globalHeader.setVisible(globalHasData);
		globalBox.setVisible(globalHasData);
		globalIntro.setVisible(globalHasData && !globalCollapsed);
		globalSub.setVisible(globalHasData && !globalCollapsed);
		globalHeader.setText("Community Claims");
		setCollapseArrow(globalHeader, globalCollapsed);
	}

	/** Builds the collapsible Leaderboards section (personal counter + opted-in clan board). Server-only;
	 *  hidden until {@link #updateLeaderboard} runs with online = true. */
	private void buildLeaderboardSection()
	{
		leaderboardHeader.setFont(HEADER_FONT);
		leaderboardHeader.setForeground(ColorScheme.BRAND_ORANGE);
		leaderboardHeader.setAlignmentX(Component.LEFT_ALIGNMENT);
		leaderboardHeader.setBorder(BorderFactory.createEmptyBorder(14, 0, 4, 0));
		leaderboardHeader.setToolTipText("Your daily and weekly tiles, and your clan's opted-in board.");
		leaderboardHeader.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		leaderboardHeader.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				leaderboardCollapsed = !leaderboardCollapsed;
				renderLeaderboard();
				revalidate();
				repaint();
			}
		});
		leaderboardBox.setLayout(new BoxLayout(leaderboardBox, BoxLayout.Y_AXIS));
		leaderboardBox.setOpaque(false);
		leaderboardBox.setAlignmentX(Component.LEFT_ALIGNMENT);
		lbRowsPanel.setLayout(new BoxLayout(lbRowsPanel, BoxLayout.Y_AXIS));
		lbRowsPanel.setOpaque(false);
		lbRowsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		leaderboardBox.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		leaderboardHeader.setVisible(false);
		leaderboardBox.setVisible(false);
	}

	/**
	 * Feed the Leaderboards section: your persistent daily/weekly totals, whether you're opted in, whether
	 * we're online (the section is server-only), your clan's opted-in board, and your own name to bold your
	 * row. Rebuilds the section.
	 */
	void updateLeaderboard(int daily, int weekly, boolean optedIn, boolean online,
			java.util.List<ClanTurfStore.LeaderboardEntry> board,
			java.util.List<ClanTurfStore.LeaderboardEntry> boardAll, String myName, boolean ready,
			java.util.Map<String, javax.swing.Icon> rankIcons, String clanName, String dayWinner, String weekWinner,
			String dayWinnerAll, String weekWinnerAll,
			long dayWinnerVal, long weekWinnerVal, long dayWinnerAllVal, long weekWinnerAllVal)
	{
		lbDaily = daily;
		lbWeekly = weekly;
		lbOptedIn = optedIn;
		leaderboardOnline = online;
		lbBoard = board == null ? java.util.Collections.emptyList() : board;
		lbBoardAll = boardAll == null ? java.util.Collections.emptyList() : boardAll;
		lbMyName = myName;
		lbReady = ready;
		lbRankIcons = rankIcons == null ? java.util.Collections.emptyMap() : rankIcons;
		lbClanName = clanName == null ? "" : clanName;
		lbDayWinner = dayWinner == null ? "" : dayWinner;
		lbWeekWinner = weekWinner == null ? "" : weekWinner;
		lbDayWinnerAll = dayWinnerAll == null ? "" : dayWinnerAll;
		lbWeekWinnerAll = weekWinnerAll == null ? "" : weekWinnerAll;
		lbDayWinnerVal = dayWinnerVal;
		lbWeekWinnerVal = weekWinnerVal;
		lbDayWinnerAllVal = dayWinnerAllVal;
		lbWeekWinnerAllVal = weekWinnerAllVal;
		renderLeaderboard();
	}

	private void renderLeaderboard()
	{
		// The active board depends on the scope tab: ALL = every opted-in player server-wide, CLAN = just yours.
		java.util.List<ClanTurfStore.LeaderboardEntry> activeBoard = lbScope == LbScope.ALL ? lbBoardAll : lbBoard;
		// Optimistic: show MY live local count on my own row so I climb the instant I claim a tile, instead of
		// waiting for the server poll to echo back tiles I collected myself. Override only my row with the max of
		// its server value and my local count; everyone else stays server-authoritative.
		if (lbMyName != null && !lbMyName.isEmpty() && (lbDaily > 0 || lbWeekly > 0))
		{
			java.util.List<ClanTurfStore.LeaderboardEntry> opt = new ArrayList<>(activeBoard.size());
			for (ClanTurfStore.LeaderboardEntry e : activeBoard)
			{
				if (e.name != null && e.name.equalsIgnoreCase(lbMyName)
						&& (lbDaily > e.daily || lbWeekly > e.weekly))
				{
					opt.add(new ClanTurfStore.LeaderboardEntry(e.name,
							Math.max(e.daily, lbDaily), Math.max(e.weekly, lbWeekly)));
				}
				else
				{
					opt.add(e);
				}
			}
			activeBoard = opt;
		}
		// Deterministic order (active period desc, then name) so an identical board from a differently-ordered
		// poll produces the same signature and we skip the rebuild - otherwise the section flickers each poll.
		java.util.List<ClanTurfStore.LeaderboardEntry> sorted = new ArrayList<>(activeBoard);
		sorted.sort(java.util.Comparator
				.comparingLong((ClanTurfStore.LeaderboardEntry e) -> lbSort == LbSort.WEEKLY ? e.weekly : e.daily)
				.reversed()
				.thenComparing(e -> e.name == null ? "" : e.name.toLowerCase()));

		// Show only players with at least one tile in the active period, so the board reflects activity rather than
		// the full opt-in roster - an opted-in player who hasn't claimed today (or this week) stays off it.
		java.util.List<ClanTurfStore.LeaderboardEntry> visible = new ArrayList<>();
		for (ClanTurfStore.LeaderboardEntry e : sorted)
		{
			if ((lbSort == LbSort.WEEKLY ? e.weekly : e.daily) >= 1)
			{
				visible.add(e);
			}
		}

		// A view change (Daily<->Weekly, All<->Clan, or a page flip) shows different numbers per row, so snap the
		// count-up to the new view instead of animating from the old view's values - drop the shown values so
		// retargetRows re-seeds each row at its current number.
		if (lbSort != lastRenderSort || lbScope != lastRenderScope || lbPage != lastRenderPage)
		{
			lbRowShown.clear();
			lastRenderSort = lbSort;
			lastRenderScope = lbScope;
			lastRenderPage = lbPage;
		}
		// Point each row's count at its latest value and kick the count-up BEFORE the rebuild guard below, so a
		// pure value change (a server poll with no reorder) still rolls the numbers up without rebuilding the rows.
		retargetRows(visible);
		startLbAnim();
		applyMineLabel(); // keep the instant local counter current even when the rows below don't rebuild

		// Clamp the page in case the board shrank (opt-outs, period reset) or the scope/sort just changed.
		int pageCount = Math.max(1, (visible.size() + LB_PAGE_SIZE - 1) / LB_PAGE_SIZE);
		if (lbPage >= pageCount)
		{
			lbPage = pageCount - 1;
		}
		if (lbPage < 0)
		{
			lbPage = 0;
		}
		int pageRows = Math.min(LB_PAGE_SIZE, Math.max(0, visible.size() - lbPage * LB_PAGE_SIZE));

		// Leaderboard hides at the login screen along with everything else - it needs a live session, not just
		// server mode, to show. Gated on signedIn too, and signedIn is in the signature so logout re-renders.
		boolean lbShow = leaderboardOnline && signedIn;

		// Medal color for your own "Your tiles" counters: your podium rank on the plugin-wide board, per period.
		Color myDailyMedal = myPodiumColor(false);
		Color myWeeklyMedal = myPodiumColor(true);

		String gray = hex(ColorScheme.LIGHT_GRAY_COLOR);
		boolean empty = visible.isEmpty();

		// Keep the persistent "Your tiles" counter and its medal-color fade current every render, independent of the
		// rebuilds below - so your own counter and its color update even when neither the chrome nor the rows rebuild.
		if (mineLabel == null)
		{
			mineLabel = new JLabel();
			mineLabel.setFont(FontManager.getRunescapeFont());
			mineLabel.setForeground(Color.WHITE);
			mineLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			mineLabel.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		}
		Color dTarget = myDailyMedal != null ? myDailyMedal : Color.WHITE;
		Color wTarget = myWeeklyMedal != null ? myWeeklyMedal : Color.WHITE;
		if (!dTarget.equals(mineDailyTarget) || !wTarget.equals(mineWeeklyTarget))
		{
			mineDailyFrom = mineDailyCur;
			mineWeeklyFrom = mineWeeklyCur;
			mineDailyTarget = dTarget;
			mineWeeklyTarget = wTarget;
			long cascadeMs = lbCascadedOnce ? 0 : pageRows * REVEAL_ROW_STAGGER + REVEAL_FADE_MS;
			mineColorStartMs = System.currentTimeMillis() + cascadeMs;
			startMineColorFade();
		}
		applyMineLabel();

		// Two rebuild guards so a rank swap only rebuilds the ROW list, not the whole section (which flashes). CHROME
		// = the static frame (counter, tabs, title, previous winner, sort bar). ROWS = the ordered name/icon sequence.
		String chromeSig = lbShow + "|" + leaderboardCollapsed + "|" + lbSort + "|" + lbScope + "|" + lbOptedIn + "|"
				+ lbReady + "|" + lbClanName + "|" + lbDayWinner + "|" + lbWeekWinner + "|" + lbDayWinnerAll + "|"
				+ lbWeekWinnerAll + "|" + lbDayWinnerVal + "|" + lbWeekWinnerVal + "|" + lbDayWinnerAllVal + "|"
				+ lbWeekWinnerAllVal + "|" + empty + "|" + leaderboardDateText()
				+ "|" + ClanTurfColors.colorblind(MEDAL_FIRST).getRGB(); // color-blind toggle recolors the clan title too
		StringBuilder rb = new StringBuilder();
		rb.append(lbShow).append('|').append(leaderboardCollapsed).append('|').append(empty).append('|')
				.append(lbPage).append('|').append(pageCount).append('|').append(lbScope).append('|')
				.append(lbSort).append('|').append(lbMyName).append('|').append(lbReady)
				.append('|').append(ClanTurfColors.colorblind(MEDAL_FIRST).getRGB());
		for (ClanTurfStore.LeaderboardEntry e : sorted)
		{
			// Name + icon only, no value: order changes rebuild (the name sequence shifts), value ticks animate.
			rb.append('#').append(e.name).append(lbRankIcons.containsKey(e.name) ? 'I' : '-');
		}
		String rowsSig = rb.toString();

		boolean chromeChanged = !chromeSig.equals(lastChromeSig);
		boolean rowsChanged = !rowsSig.equals(lastRowsSig);
		if (!chromeChanged && !rowsChanged)
		{
			return; // nothing displayed changed - no rebuild, no flicker
		}
		lastChromeSig = chromeSig;
		lastRowsSig = rowsSig;

		leaderboardHeader.setVisible(lbShow);
		leaderboardBox.setVisible(lbShow); // box stays visible online; collapse hides only the board part
		leaderboardHeader.setText("Leaderboards");
		setCollapseArrow(leaderboardHeader, leaderboardCollapsed);

		if (chromeChanged)
		{
			rebuildLbChrome(lbShow, gray);
		}
		// Rows live in the persistent lbRowsPanel; rebuild them on an order/page change, or when the chrome was just
		// rebuilt (which re-adds an empty rows panel that needs refilling).
		if (lbShow && lbReady && !leaderboardCollapsed && (chromeChanged || rowsChanged))
		{
			rebuildLbRows(visible, pageCount, sorted.isEmpty());
		}
		leaderboardBox.revalidate();
		leaderboardBox.repaint();
	}

	/** Rebuild the static chrome of the Leaderboards section (counter, tabs, title, previous winner, sort bar) and
	 *  slot in the persistent {@link #lbRowsPanel}. Runs only when the chrome changes - never on a plain rank swap. */
	private void rebuildLbChrome(boolean lbShow, String gray)
	{
		leaderboardBox.removeAll();
		if (!lbShow)
		{
			return;
		}
		if (!lbReady)
		{
			// Board not loaded yet: show ONLY the loading line - the counter, tabs, winner, sort bar and rows all
			// stay hidden until the real board arrives, so nothing half-populated flashes up first.
			JLabel loading = new JLabel("<html><body style='width:170px'>Loading leaderboards…</body></html>");
			loading.setFont(FontManager.getRunescapeSmallFont());
			loading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			loading.setAlignmentX(Component.LEFT_ALIGNMENT);
			leaderboardBox.add(loading);
			return;
		}
		leaderboardBox.add(mineLabel); // persistent counter, shown even when collapsed
		if (leaderboardCollapsed)
		{
			return; // collapsed: only your personal line shows; the sort bar and board are hidden
		}

		// A divider sets your personal counter apart from the board below.
		leaderboardBox.add(Box.createVerticalStrut(6));
		leaderboardBox.add(thinDivider());
		leaderboardBox.add(Box.createVerticalStrut(6));

		// Scope tabs: All (every opted-in player server-wide) vs Clan (just yours). Sits above the board title.
		JPanel scopeBar = tabGroup(true, lbScopeLabel("All", LbScope.ALL), lbScopeLabel("Clan", LbScope.CLAN));
		leaderboardBox.add(scopeBar);
		leaderboardBox.add(Box.createVerticalStrut(4));

		// Anyone can view the board; opting in only decides whether you are ON it. If you haven't opted in,
		// show the board anyway with a nudge to join it.
		if (!lbOptedIn)
		{
			JLabel prompt = new JLabel("<html><body style='width:170px'>"
					+ "Toggle the leaderboard on in Opt-In Features to add your tiles here.</body></html>");
			prompt.setFont(FontManager.getRunescapeSmallFont());
			prompt.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			prompt.setAlignmentX(Component.LEFT_ALIGNMENT);
			leaderboardBox.add(prompt);
			leaderboardBox.add(Box.createVerticalStrut(4));
		}

		// Title: "Top Turfers:" server-wide, or "<Clan>'s Top Turfers:" (clan-colored possessive) for the Clan tab.
		String titleHtml;
		if (lbScope == LbScope.CLAN && !lbClanName.isEmpty())
		{
			String clanHex = hex(ClanTurfColors.forClan(lbClanName));
			titleHtml = "<span style='color:#" + clanHex + "'>" + escape(lbClanName) + "'s</span> Top Turfers:";
		}
		else
		{
			titleHtml = "Top Turfers:";
		}
		JLabel titleLbl = new JLabel("<html><body style='width:170px'>" + titleHtml + "</body></html>");
		titleLbl.setFont(FontManager.getRunescapeFont());
		titleLbl.setForeground(Color.WHITE);
		titleLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleLbl.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		leaderboardBox.add(titleLbl);

		// Previous period's winner: the plugin-wide top player on the All tab, your clan's top on the Clan tab.
		boolean showWinner = lbScope == LbScope.ALL || !lbClanName.isEmpty();
		if (showWinner)
		{
			String winner = lbScope == LbScope.ALL
					? (lbSort == LbSort.WEEKLY ? lbWeekWinnerAll : lbDayWinnerAll)
					: (lbSort == LbSort.WEEKLY ? lbWeekWinner : lbDayWinner);
			long winnerVal = lbScope == LbScope.ALL
					? (lbSort == LbSort.WEEKLY ? lbWeekWinnerAllVal : lbDayWinnerAllVal)
					: (lbSort == LbSort.WEEKLY ? lbWeekWinnerVal : lbDayWinnerVal);
			String nameCell = winner.isEmpty()
					? "<span style='color:#" + gray + "'>empty</span>"
					: escape(winner);
			String winnerLabel = lbSort == LbSort.WEEKLY ? "Last Week's Leader: " : "Yesterday's Leader: ";
			StringBuilder winnerHtml = new StringBuilder("<html><body style='width:170px'>");
			winnerHtml.append("<span style='color:#").append(gray).append("'>").append(winnerLabel).append("</span>")
					.append(nameCell);
			if (!winner.isEmpty() && winnerVal > 0)
			{
				winnerHtml.append("<br><span style='color:#").append(gray).append("'>Total Tiles: </span>")
						.append(fmt(winnerVal));
			}
			winnerHtml.append("</body></html>");
			JLabel wLbl = new JLabel(winnerHtml.toString());
			wLbl.setFont(FontManager.getRunescapeSmallFont());
			wLbl.setForeground(Color.WHITE);
			wLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
			wLbl.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));
			leaderboardBox.add(wLbl);
		}

		// Daily / Weekly sort control, with the active period's date pushed to the right of the same line.
		JPanel bar = new JPanel();
		bar.setLayout(new BoxLayout(bar, BoxLayout.X_AXIS));
		bar.setOpaque(false);
		bar.setAlignmentX(Component.LEFT_ALIGNMENT);
		bar.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
		bar.add(tabGroup(false, lbSortLabel("Daily", LbSort.DAILY), lbSortLabel("Weekly", LbSort.WEEKLY)));
		bar.add(Box.createHorizontalStrut(8));
		bar.add(Box.createHorizontalGlue());
		JLabel dateLabel = new JLabel(leaderboardDateText());
		dateLabel.setFont(FontManager.getRunescapeSmallFont());
		dateLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		bar.add(dateLabel);
		leaderboardBox.add(bar);
		leaderboardBox.add(thinDivider());
		leaderboardBox.add(Box.createVerticalStrut(4));
		leaderboardBox.add(lbRowsPanel); // the zebra rows + pager live here, rebuilt alone on a rank swap
	}

	/** Rebuild just the row list (zebra strips + pager, or the empty-state message) into {@link #lbRowsPanel} - the
	 *  only thing torn down on a rank swap, so the swap no longer flashes the counter/tabs/title above. */
	private void rebuildLbRows(java.util.List<ClanTurfStore.LeaderboardEntry> visible, int pageCount,
			boolean sortedEmpty)
	{
		lbRowsPanel.removeAll();
		lbRowLabel.clear(); // re-registered below for the rows on this page, so the animator drives the live labels
		if (visible.isEmpty())
		{
			// Distinguish "no one opted in" from "people are opted in but no one has tiles this period yet".
			String period = lbSort == LbSort.WEEKLY ? "this week" : "today";
			String msg = !lbReady ? "Loading leaderboards…"
					: !sortedEmpty ? "No tiles claimed " + period + " yet."
					: lbScope == LbScope.CLAN ? "No one in your clan has opted in yet."
					: "No one has opted in yet.";
			JLabel none = new JLabel("<html><body style='width:170px'>" + escape(msg) + "</body></html>");
			none.setFont(FontManager.getRunescapeSmallFont());
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			none.setAlignmentX(Component.LEFT_ALIGNMENT);
			lbRowsPanel.add(none);
			lbRowsPanel.revalidate();
			lbRowsPanel.repaint();
			return;
		}

		// One page of LB_PAGE_SIZE rows. Rank numbers are GLOBAL within the active board (page offset + index), so
		// #1 is gold/bold only on the real top and page 2 continues at 11, not back at 1.
		int from = lbPage * LB_PAGE_SIZE;
		int to = Math.min(from + LB_PAGE_SIZE, visible.size());
		boolean cascade = !lbCascadedOnce; // rows fade in top-down only on the first load this session
		long cascadeBase = System.currentTimeMillis();
		for (int i = from; i < to; i++)
		{
			ClanTurfStore.LeaderboardEntry e = visible.get(i);
			int rank = i + 1;
			long v = lbSort == LbSort.WEEKLY ? e.weekly : e.daily;
			// Podium (ranks 1-3) wears its medal color on the text (color-blind adjusted); #1 is also bold.
			Color medal = rank == 1 ? MEDAL_FIRST : rank == 2 ? MEDAL_SECOND : rank == 3 ? MEDAL_THIRD : null;
			Color fg = medal != null ? ClanTurfColors.colorblind(medal) : Color.WHITE;
			java.awt.Font font = FontManager.getRunescapeFont();
			if (rank == 1)
			{
				font = font.deriveFont(java.awt.Font.BOLD);
			}

			// v9 zebra strip: alternate ROW_A / ROW_B (page row 0 is the lighter ROW_A), with a 2px PANEL_BG
			// gap between rows. Your own row keeps the zebra shade; only a 2px ACCENT stripe on the left marks it.
			boolean mine = lbMyName != null && e.name != null && e.name.equalsIgnoreCase(lbMyName);
			Color rowBg = (i - from) % 2 == 0 ? ROW_A : ROW_B;
			FadePanel row = new FadePanel(new BorderLayout(4, 0));
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.setFill(rowBg); // zebra fill painted as content (not opaque bg), so the cascade fade stays clean
			// Left edge: 2px ACCENT stripe for your row, otherwise 2px of the row's own fill so text never shifts.
			row.setBorder(BorderFactory.createCompoundBorder(
					new javax.swing.border.MatteBorder(0, 2, 0, 0, mine ? ACCENT : rowBg),
					BorderFactory.createEmptyBorder(5, 2, 5, 4)));

			// rank number, then the clan-rank icon (Clan tab only - the All tab is name-only), then the name
			JPanel leftGroup = new JPanel();
			leftGroup.setLayout(new BoxLayout(leftGroup, BoxLayout.X_AXIS));
			leftGroup.setOpaque(false);
			JLabel num = new JLabel(rank + ". ");
			num.setFont(font);
			num.setForeground(fg);
			num.setAlignmentY(Component.CENTER_ALIGNMENT);
			leftGroup.add(num);
			// One label carries the clan-rank icon AND the name, so Swing centers the icon to the text
			// (a separate icon label sits low against the text's descender). Icon is null-safe here.
			javax.swing.Icon ic = lbScope == LbScope.CLAN ? lbRankIcons.get(e.name) : null;
			JLabel nameL = new JLabel(e.name, ic, JLabel.LEFT);
			nameL.setIconTextGap(3);
			nameL.setFont(font);
			nameL.setForeground(fg);
			nameL.setAlignmentY(Component.CENTER_ALIGNMENT);
			leftGroup.add(nameL);
			// CENTER (not WEST) so the name group absorbs the leftover width: WEST takes only its preferred
			// size and BorderLayout squeezes it first, so a vertical scrollbar stealing ~15px was ellipsizing
			// names with space to spare. CENTER gets (row width - the fixed count slot), which fits them.
			row.add(leftGroup, BorderLayout.CENTER);

			// Fixed-width, right-aligned count slot: a number changing digit count (9 -> 2211) must not
			// resize the row, or the whole panel's width oscillates and the text jumps around.
			// Seed from the animator's shown value (which eases up toward v for server rows, snaps for my own)
			// and register the label so tickLbAnim can roll the number in place without a rebuild.
			long shownV = lbRowShown.getOrDefault(e.name, v);
			JLabel count = new JLabel(String.valueOf(shownV), JLabel.RIGHT);
			count.setFont(font);
			count.setForeground(fg); // top 3 in their rank color, everyone else white (fg is white when not top 3)
			Dimension cd = new Dimension(54, count.getPreferredSize().height);
			count.setPreferredSize(cd);
			count.setMinimumSize(cd);
			count.setMaximumSize(cd);
			row.add(count, BorderLayout.EAST);
			if (e.name != null)
			{
				lbRowLabel.put(e.name, count);
			}

			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			if (cascade)
			{
				scheduleReveal(row, cascadeBase + (i - from) * REVEAL_ROW_STAGGER); // top-down cascade
			}
			lbRowsPanel.add(row);
			if (i < to - 1)
			{
				lbRowsPanel.add(Box.createVerticalStrut(2)); // 2px PANEL_BG gap between zebra strips
			}
		}
		lbCascadedOnce = true; // only the first board render cascades; tab switches and polls render instantly

		// Clickable page numbers, only when the board spans more than one page. A thin divider sets them off
		// from the last row above.
		if (pageCount > 1)
		{
			lbRowsPanel.add(Box.createVerticalStrut(5));
			lbRowsPanel.add(thinDivider());
			lbRowsPanel.add(Box.createVerticalStrut(4));
			lbRowsPanel.add(buildPager(lbPage, pageCount, pg ->
			{
				lbPage = pg;
				lbCascadedOnce = false; // re-cascade on a page change
				renderLeaderboard();
				revalidate();
				repaint();
			}));
		}

		lbRowsPanel.revalidate();
		lbRowsPanel.repaint();
	}

	/** Medal color for the local player's rank on the ACTIVE board (All or Clan tab) for the given period, or null
	 *  if they are not top-3 (or not opted in / have no tiles). Drives the "Your tiles" counter colors. */
	private Color myPodiumColor(boolean weekly)
	{
		if (!lbOptedIn)
		{
			return null; // opted out: your tiles are plain white, even if the board still lists you this poll
		}
		java.util.List<ClanTurfStore.LeaderboardEntry> src = lbScope == LbScope.ALL ? lbBoardAll : lbBoard;
		if (lbMyName == null || lbMyName.isEmpty() || src.isEmpty())
		{
			return null;
		}
		java.util.List<ClanTurfStore.LeaderboardEntry> board = new ArrayList<>(src);
		board.sort(java.util.Comparator
				.comparingLong((ClanTurfStore.LeaderboardEntry e) -> weekly ? e.weekly : e.daily)
				.reversed()
				.thenComparing(e -> e.name == null ? "" : e.name.toLowerCase()));
		int rank = 0;
		for (int i = 0; i < board.size(); i++)
		{
			ClanTurfStore.LeaderboardEntry e = board.get(i);
			if ((weekly ? e.weekly : e.daily) < 1)
			{
				break; // zero-tile players are not ranked (matches the board's activity filter); stop once we hit them
			}
			if (e.name != null && e.name.equalsIgnoreCase(lbMyName))
			{
				rank = i + 1;
				break;
			}
		}
		Color medal = rank == 1 ? MEDAL_FIRST : rank == 2 ? MEDAL_SECOND : rank == 3 ? MEDAL_THIRD : null;
		return ClanTurfColors.colorblind(medal); // shift with the color-blind toggle like clan colors do
	}

