	/** Row of clickable page numbers (windowed with ellipses). Shared by the leaderboard and Active Battles;
	 *  onSelect is called with the chosen zero-based page. */
	private JPanel buildPager(int page, int pageCount, java.util.function.IntConsumer onSelect)
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.X_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setBorder(BorderFactory.createEmptyBorder(6, 7, 6, 0)); // inset + vertical gap, separate from the rows/cards
		boolean first = true;
		for (int pg : pagerPages(page, pageCount))
		{
			if (!first)
			{
				p.add(Box.createHorizontalStrut(6)); // a touch more gap between page blocks
			}
			first = false;
			if (pg < 0)
			{
				JLabel gap = new JLabel("…");
				gap.setFont(FontManager.getRunescapeSmallFont());
				gap.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				p.add(gap);
				continue;
			}
			p.add(pageNumLabel(pg, page, onSelect));
		}
		p.add(Box.createHorizontalGlue());
		return p;
	}

	/** Page tokens to show: all of them when there are few, else first, last, and a window around the current
	 *  page, with -1 marking an ellipsis gap. */
	private java.util.List<Integer> pagerPages(int cur, int count)
	{
		java.util.List<Integer> out = new ArrayList<>();
		if (count <= 7)
		{
			for (int i = 0; i < count; i++)
			{
				out.add(i);
			}
			return out;
		}
		out.add(0);
		int lo = Math.max(1, cur - 1);
		int hi = Math.min(count - 2, cur + 1);
		if (lo > 1)
		{
			out.add(-1);
		}
		for (int i = lo; i <= hi; i++)
		{
			out.add(i);
		}
		if (hi < count - 2)
		{
			out.add(-1);
		}
		out.add(count - 1);
		return out;
	}

	/** One clickable page number (1-based display) as a 22x22 square tab block; the current page is the inert,
	 *  lighter, underlined one. */
	private JLabel pageNumLabel(int pg, int active, java.util.function.IntConsumer onSelect)
	{
		boolean isActive = pg == active;
		JLabel l = tabButton(String.valueOf(pg + 1), isActive, isActive ? null : () -> onSelect.accept(pg));
		if (!isActive)
		{
			l.setOpaque(false); // inactive page numbers get no box; only the current page shows the lighter fill
		}
		Dimension sq = new Dimension(TAB_H, TAB_H); // square block, matching the guide's 22x22
		l.setPreferredSize(sq);
		l.setMinimumSize(sq);
		l.setMaximumSize(sq);
		return l;
	}

	/** Date label for the active period: "Thu 17" for Daily, "Mon 21 - Sun 27" for the current UTC week. */
	private String leaderboardDateText()
	{
		java.time.LocalDate today = java.time.LocalDate.now(java.time.ZoneOffset.UTC);
		java.time.format.DateTimeFormatter f =
				java.time.format.DateTimeFormatter.ofPattern("EEE d", java.util.Locale.ENGLISH);
		if (lbSort == LbSort.WEEKLY)
		{
			java.time.LocalDate mon = today.with(
					java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY));
			return mon.format(f) + " - " + mon.plusDays(6).format(f);
		}
		return today.format(f);
	}

