	/** The battle for a given world from the shared board, or null if it isn't contested. */
	private ClanTurfBattle findBattle(int world)
	{
		for (ClanTurfBattle b : store.getBattles())
		{
			if (b.getWorld() == world)
			{
				return b;
			}
		}
		return null;
	}

	private boolean senderIsLocalPlayer(ChatMessage event)
	{
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return false;
		}
		return Text.sanitize(event.getName()).equalsIgnoreCase(Text.sanitize(local.getName()));
	}

	/** Posts a Clan Turf line into the clan chat tab (a clan system message) so all plugin chatter
	 * lives in one place. Renders only for players who are in a clan. */
	private void announceClan(String message)
	{
		client.addChatMessage(ChatMessageType.CLAN_MESSAGE, "", message, null);
	}

	/** Milliseconds until the next daily turf reset (fixed UTC hour, matching the server). Read by
	 * the on-screen countdown overlay, which shows everywhere in the final minutes. */
	long msUntilReset()
	{
		ZonedDateTime now = ZonedDateTime.now(ZoneOffset.UTC);
		ZonedDateTime next = now.withHour(RESET_HOUR_UTC).withMinute(0).withSecond(0).withNano(0);
		if (!next.isAfter(now))
		{
			next = next.plusDays(1);
		}
		return Duration.between(now, next).toMillis();
	}

	/**
	 * Warns in the clan tab as the daily reset approaches, but only while at the GE (like the other
	 * announcements). Each threshold is consumed by time passing whether or not you're present, so
	 * arriving late doesn't dump every past warning at once; a message only shows if you're at the
	 * GE the moment the threshold is crossed.
	 */
	private void updateResetPings(boolean nearGe)
	{
		if (!config.resetCountdown())
		{
			return;
		}
		long ms = msUntilReset();
		if (ms > RESET_PING_CLEAR_MS)
		{
			prevResetMs = -1L; // outside the window -> re-baseline for the next day
			return;
		}
		if (prevResetMs < 0L)
		{
			// First tick this cycle (login or just entered the window): baseline only, so a
			// threshold already passed before we started watching doesn't fire retroactively.
			prevResetMs = ms;
		}
		for (int t : RESET_PING_MINUTES)
		{
			long mark = t * 60_000L;
			if (prevResetMs > mark && ms <= mark && nearGe)
			{
				announceClan(CT_TAG + " " + WHITE + "Turf resets in " + t
						+ (t == 1 ? " minute" : " minutes") + "!" + RESET);
			}
		}
		prevResetMs = ms;
	}

	/** After the daily reset, announce the turf-war winner for your world once, naming the clan/alliance the
	 *  server recorded as owning the most tiles at the wipe. Two independent outputs, each on its own toggle:
	 *  the clan-tab line follows the reset-countdown toggle (the reset messaging feature), and the NPC victory
	 *  chorus follows the NPC bark toggle (the single switch for all barking). Gated to near the GE, and waits
	 *  up to 5 minutes for the winner to arrive on the next battles poll so it uses the server's authoritative
	 *  result rather than this client's last-seen owner. */
	private void maybeAnnounceWinner(boolean nearGe)
	{
		if (!pendingWinnerAnnounce || store != serverStore)
		{
			return;
		}
		boolean wantChat = config.resetCountdown(); // reset messaging owns the clan-tab line
		boolean wantBark = config.npcBarks();       // the one NPC bark toggle owns the victory chorus
		if (!wantChat && !wantBark)
		{
			pendingWinnerAnnounce = false; // neither output enabled, nothing to announce
			return;
		}
		if (System.currentTimeMillis() - winnerPendingSinceMs > 5L * 60 * 1000)
		{
			pendingWinnerAnnounce = false; // gave up: the winner never arrived in time
			return;
		}
		if (!nearGe)
		{
			return; // only announce to players at the GE, like the countdown pings
		}
		int world = client.getWorld();
		String winner = store.turfWinner(world);
		if (winner == null)
		{
			return; // not fetched from the server yet; try again next tick
		}
		pendingWinnerAnnounce = false;
		if (wantChat)
		{
			String on = "<col=" + hex(ClanTurfColors.forClan(winner)) + ">";
			String name = winner.toUpperCase(java.util.Locale.ROOT);
			String msg = on + "[CT]" + RESET + " " + on + name + RESET + WHITE + " won the turf war on " + RESET
					+ on + "World " + world + RESET + WHITE + "!" + RESET;
			announceClan(msg);
		}
		fireTakeoverBarks(winner, true); // victory chorus; fireTakeoverBarks self-gates on the NPC bark toggle
	}

	/** RRGGBB hex for a colour, for chat {@code <col=...>} tags. */
	private static String hex(Color c)
	{
		return String.format("%02x%02x%02x", c.getRed(), c.getGreen(), c.getBlue());
	}


	private void refreshClaims()
	{
		int world = client.getWorld();
		visibleClaims = new java.util.ArrayList<>(store.getClaims(world));
		if (panel == null)
		{
			return;
		}
		// If the alliance set changed since the last paint (e.g. a disband/leave just cleared it), re-apply
		// the team colors NOW, before painting. Otherwise the scoreboard shows a just-freed clan in its old
		// alliance color for one frame until onGameTick catches up (the "flash back to purple").
		if (!store.allianceColors().equals(lastAllianceColors)
				|| !store.allianceNames().equals(lastAllianceNames)
				|| !store.allianceHomeWorlds().equals(lastAllianceHomes))
		{
			applyWhitelist();
			leaderInit = false;
		}
		updateAlliancePanel();
		// Before login there's no world and no reason to mention the server: startUp() calls this at
		// the login screen, where "Connecting to the sync server..." is nonsense. Show a plain waiting
		// message until we're actually in-game; the connection wording only kicks in once logged in.
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.showEmpty("Waiting for the client…");
			panel.updateBattles(Collections.emptyList(), effectiveClanName(), -1);
			return;
		}
		panel.update(aggregatedClaims(), world, GrandExchangeArea.totalTiles(), committedLeader,
				displayClan(effectiveClanName()), findBattle(world), store.connectionStatus(), clanHintDue(),
				perClanTileCounts());
		panel.updateBattles(battlesForPanel(), displayClan(effectiveClanName()), client.getWorld());
		panel.setGlobalClaims(store.getGlobalClaims());
		pushLeaderboardToPanel();
	}

	/** Feed the panel's Leaderboards section with the personal counter and the opted-in clan board. Clan
	 *  rank icons are resolved here on the game thread (they read the clan channel) and passed as ready
	 *  images, so the Swing panel never touches the client. */
	private void pushLeaderboardToPanel()
	{
		if (panel == null)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		String myName = me == null ? null : me.getName();
		java.util.List<ClanTurfStore.LeaderboardEntry> board = getClanLeaderboard();
		java.util.List<ClanTurfStore.LeaderboardEntry> boardAll = store.getAllLeaderboard(); // plugin-wide "All" tab
		java.util.Map<String, javax.swing.Icon> icons = new java.util.HashMap<>();
		ClanChannel ch = client.getClanChannel();
		ClanSettings cs = client.getClanSettings();
		if (cs != null)
		{
			// Rank icons come from your own clan roster, so only clan-board names resolve; the All tab shows
			// names without icons. Resolve for the clan board here (ClanSettings covers offline members too).
			for (ClanTurfStore.LeaderboardEntry e : board)
			{
				javax.swing.Icon ic = rankIcon(ch, cs, e.name);
				if (ic != null)
				{
					icons.put(e.name, ic);
				}
			}
		}
		// The board and winners are keyed by your real clan (not the alliance), so use the raw clan name
		// here - displayClan() would collapse it to the alliance name like the scoreboard does.
		String clan = effectiveClanName();
		panel.updateLeaderboard(getLeaderboardDaily(), getLeaderboardWeekly(), config.leaderboardOptIn(),
				store == serverStore, board, boardAll, myName, store.leaderboardReady(), icons,
				clan == null ? "" : clan, store.leaderboardDayWinner(clan), store.leaderboardWeekWinner(clan),
				store.leaderboardDayWinnerAll(), store.leaderboardWeekWinnerAll(),
				store.leaderboardDayWinnerValue(clan), store.leaderboardWeekWinnerValue(clan),
				store.leaderboardDayWinnerValueAll(), store.leaderboardWeekWinnerValueAll());
	}

	/** The clan-rank icon for a member of your clan (null if they aren't in your clan, their rank has no
	 *  title, or the rank images haven't loaded yet - the icon then just appears on a later refresh).
	 *  Ranks come from ClanSettings (the full member roster), so OFFLINE clanmates on the board still get
	 *  their icon; the ClanChannel (online members only) is just a fallback if settings isn't loaded yet. */
	private javax.swing.Icon rankIcon(ClanChannel ch, ClanSettings cs, String name)
	{
		if (name == null || cs == null)
		{
			return null;
		}
		ClanRank rank = null;
		ClanMember sm = cs.findMember(name); // full roster, online or offline
		if (sm != null)
		{
			rank = sm.getRank();
		}
		else if (ch != null)
		{
			ClanChannelMember cm = ch.findMember(name); // fallback: currently-online channel
			if (cm != null)
			{
				rank = cm.getRank();
			}
		}
		if (rank == null)
		{
			return null;
		}
		ClanTitle title = cs.titleForRank(rank);
		if (title == null)
		{
			return null;
		}
		java.awt.image.BufferedImage img = chatIconManager.getRankImage(title);
		return img == null ? null : new javax.swing.ImageIcon(img);
	}

