package com.zezizaza.clanturf;

import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The seam. Everything above this interface (claim detection, overlay, panel) is
 * backend-agnostic; everything about <em>where tiles live and how they sync</em> lives
 * behind it.
 *
 * <p>V1 ships {@link ConfigClanTurfStore}, which persists to ConfigManager and is
 * therefore local-only - you see your own clan's claims and no one else's. When a
 * realtime backend is added, it implements this same interface: {@link #putClaim} also
 * publishes the claim, and incoming remote claims land via the same {@link #putClaim}
 * before {@link #setChangeListener} fires to repaint. No caller changes.
 */
interface ClanTurfStore
{
	/**
	 * @param world the world whose ownership we are looking at ({@code client.getWorld()})
	 * @return every claimed tile in that world, across the tracked region(s)
	 */
	Collection<ClanTurfPoint> getClaims(int world);

	/**
	 * Record a claim. Last writer wins - walking onto a tile another clan holds
	 * overwrites it, which is exactly the takeover rule. A backend implementation would
	 * additionally broadcast here.
	 */
	void putClaim(ClanTurfPoint point);

	/**
	 * Remove every claim in the given world (across all tracked regions). Fires the change
	 * listener so the overlay and panel clear. Handy for testing.
	 */
	void clearClaims(int world);

	/**
	 * Remove a single tile's claim, if present (used by the offline eraser). Default no-op: only the
	 * local store implements it, since erasing is an offline-only sandbox tool.
	 */
	default void removeClaim(ClanTurfPoint point)
	{
	}

	/**
	 * Register a callback fired whenever the claim set changes (local write today; also
	 * remote writes once a backend exists) so the overlay/panel can repaint. The local
	 * store only ever calls this from its own {@link #putClaim}.
	 */
	default void setChangeListener(Runnable onChange)
	{
	}

	/**
	 * Active-world summaries for the "active battles" board. Only the networked store returns
	 * anything; local play has no cross-world view, so this is empty.
	 */
	default List<ClanTurfBattle> getBattles()
	{
		return Collections.emptyList();
	}

	/**
	 * All-time community total of tiles claimed across everyone (the "Global Claims" counter). Only the
	 * networked store reports a real number; local play has no shared total, so this is 0.
	 */
	default long getGlobalClaims()
	{
		return 0;
	}

	/**
	 * Alliance color for every clan currently in an alliance: clan name -> 6-hex RRGGBB, so the
	 * overlay can paint allied clans in their shared color. Only the networked store has alliances.
	 */
	default Map<String, String> allianceColors()
	{
		return Collections.emptyMap();
	}

	/** The alliance id a clan belongs to (case-insensitive), or null if it isn't in one. */
	default String allianceIdOf(String clan)
	{
		return null;
	}

	/** Every clan in the same alliance as {@code clan} (including it), or empty if it has none. */
	default Set<String> alliesOf(String clan)
	{
		return Collections.emptySet();
	}

	/** The display name of a clan's alliance, or null if it isn't in one (or the alliance is unnamed). */
	default String allianceNameOf(String clan)
	{
		return null;
	}

	/** The clan that created (owns) a clan's alliance, or null. Its Admin+ staff manage the alliance. */
	default String allianceOwnerClanOf(String clan)
	{
		return null;
	}

	/** The alliance's chosen symbol (a clan-motif sprite id), or 0 if none/unknown. */
	default int allianceIconOf(String clan)
	{
		return 0;
	}

	/** The symbol sprite id for an alliance addressed by its display name (or id), or 0 if not an alliance. */
	default int allianceIconByDisplay(String display)
	{
		return 0;
	}

	/** A clan's alliance home world, or 0 if unset/not in an alliance. Networked store only. */
	default int allianceHomeWorldOf(String clan)
	{
		return 0;
	}

	/** The home world for an alliance addressed by its display name (or id), or 0 if unset. Networked only. */
	default int allianceHomeWorldByDisplay(String display)
	{
		return 0;
	}

	/** All alliance home worlds (alliance id -> world), for detecting a change. Networked store only. */
	default Map<String, Integer> allianceHomeWorlds()
	{
		return Collections.emptyMap();
	}

	/** The member clans of an alliance addressed by its display name (or id); empty if not an alliance. */
	default List<String> allianceMembersByDisplay(String display)
	{
		return Collections.emptyList();
	}

	/** Every allied clan mapped to its alliance's display name, for detecting a rename (colors miss it). */
	default Map<String, String> allianceNames()
	{
		return Collections.emptyMap();
	}

	/** A player's opted-in alliance badge for overhead indicators: the shared color, symbol and name. */
	final class AllianceTag
	{
		final String colorHex;   // 6-hex RRGGBB
		final int icon;          // clan-motif sprite id, 0 if none
		final String allianceId; // alliance id, so the overlay can match the conquering alliance for a sparkle

		AllianceTag(String colorHex, int icon, String allianceId)
		{
			this.colorHex = colorHex;
			this.icon = icon;
			this.allianceId = allianceId;
		}
	}

	/** The alliance id whose display name (or id) is {@code display}, or null. Networked store only. */
	default String allianceIdByDisplay(String display)
	{
		return null;
	}

	/**
	 * The opt-in alliance badge a player (addressed by standardized RSN) has published, for overhead
	 * indicators, or null if they aren't on the roster or their alliance is gone. Networked store only.
	 */
	default AllianceTag allianceTagForPlayer(String playerName)
	{
		return null;
	}

	/** One opted-in player's line on a clan's daily/weekly tile leaderboard. */
	final class LeaderboardEntry
	{
		final String name;
		final long daily;
		final long weekly;

		LeaderboardEntry(String name, long daily, long weekly)
		{
			this.name = name;
			this.daily = daily;
			this.weekly = weekly;
		}
	}

	/**
	 * The opted-in members of {@code clan} on the daily/weekly tile leaderboard, unsorted. Only the
	 * networked store returns anything; local play has no shared board.
	 */
	default List<LeaderboardEntry> getLeaderboard(String clan)
	{
		return Collections.emptyList();
	}

	/**
	 * Every opted-in player across all clans (the server-wide "All" leaderboard), unsorted. Only the
	 * networked store returns anything; local play has no shared board.
	 */
	default List<LeaderboardEntry> getAllLeaderboard()
	{
		return Collections.emptyList();
	}

	/** Publish this player's current daily/weekly tile totals to the leaderboard (opt-in). Networked only. */
	default void leaderboardSubmit(String name, String clan, long daily, long weekly)
	{
	}

	/**
	 * Add to this player's authoritative daily/weekly tile totals on the server (opt-in, networked only).
	 * Sends a delta (normally 1 per claim), never a total, so the same account played on two devices adds up
	 * instead of one machine overwriting the other. Used with a one-time seed of the existing local totals at
	 * opt-in. The server holds the result so it follows the account across devices.
	 */
	default void leaderboardAdd(String name, String clan, long dailyDelta, long weeklyDelta)
	{
	}

	/** Remove this player from the leaderboard (opt-out or clan change). Networked only. */
	default void leaderboardOptOut(String name)
	{
	}

	/** The clan/alliance that owned the most tiles on {@code world} at the last daily reset (captured
	 *  server-side just before the wipe), or null if unknown. Networked only; drives the reset winner ping. */
	default String turfWinner(int world)
	{
		return null;
	}

	/** Force an immediate leaderboard poll (e.g. right after opting in), so the board isn't stale. */
	default void refreshLeaderboard()
	{
	}

	/** True once at least one leaderboard poll has completed, so the panel can say "Loading" before that
	 *  instead of "no one has opted in." The local store has no board, so it is trivially ready. */
	default boolean leaderboardReady()
	{
		return true;
	}

	/** The player who topped a clan's board for the just-ended day, or null if unknown. Networked store only. */
	default String leaderboardDayWinner(String clan)
	{
		return null;
	}

	/** The player who topped a clan's board for the just-ended week, or null if unknown. Networked store only. */
	default String leaderboardWeekWinner(String clan)
	{
		return null;
	}

	/** The single plugin-wide top player for the just-ended day (All tab), or "" if unknown. Networked only. */
	default String leaderboardDayWinnerAll()
	{
		return "";
	}

	/** The single plugin-wide top player for the just-ended week (All tab), or "" if unknown. Networked only. */
	default String leaderboardWeekWinnerAll()
	{
		return "";
	}

	/** The tile total the clan's just-ended-day winner had, or 0 if unknown. Networked store only. */
	default long leaderboardDayWinnerValue(String clan)
	{
		return 0;
	}

	/** The tile total the clan's just-ended-week winner had, or 0 if unknown. Networked store only. */
	default long leaderboardWeekWinnerValue(String clan)
	{
		return 0;
	}

	/** The tile total the plugin-wide just-ended-day winner had (All tab), or 0 if unknown. Networked only. */
	default long leaderboardDayWinnerValueAll()
	{
		return 0;
	}

	/** The tile total the plugin-wide just-ended-week winner had (All tab), or 0 if unknown. Networked only. */
	default long leaderboardWeekWinnerValueAll()
	{
		return 0;
	}

	/** Start any background work (e.g. the sync poller). No-op for the local store. */
	default void start()
	{
	}

	/** Stop background work and release resources. No-op for the local store. */
	default void stop()
	{
	}

	/**
	 * Rough connection health, used only to word the panel's empty state so a cold start or a
	 * down server reads as such instead of the misleading "no tiles claimed yet." The local
	 * store never talks to a server, so it is always {@link ConnectionStatus#ONLINE}.
	 */
	default ConnectionStatus connectionStatus()
	{
		return ConnectionStatus.ONLINE;
	}

	/** Connection health for the sidebar's empty state. */
	enum ConnectionStatus
	{
		/** Started but no reply from the server yet (cold start, first poll in flight). */
		CONNECTING,
		/** Heard back from the server recently. */
		ONLINE,
		/** Been trying a while with no reply, or lost contact - server likely down. */
		OFFLINE
	}
}

