/**
 * Color-vision deficiency modes. When set, {@link ClanTurfColors} daltonizes every clan color -
 * auto and custom alike - so confusable clans separate more for that type of color blindness.
 */
public enum ColorblindMode
{
	NONE("None"),
	PROTANOPIA("Protanopia"),
	DEUTERANOPIA("Deuteranopia"),
	TRITANOPIA("Tritanopia");

	private final String label;

	ColorblindMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

