	@Override
	public List<LeaderboardEntry> getLeaderboard(String clan)
	{
		if (clan == null)
		{
			return Collections.emptyList();
		}
		List<LeaderboardEntry> l = leaderboardByClan.get(clan.toLowerCase());
		return l == null ? Collections.emptyList() : l;
	}

	@Override
	public List<LeaderboardEntry> getAllLeaderboard()
	{
		// Flatten every clan's opted-in entries into one server-wide list. Each opt-in belongs to exactly one
		// clan, so this is already de-duplicated by player. The panel sorts and paginates it.
		List<LeaderboardEntry> all = new ArrayList<>();
		for (List<LeaderboardEntry> l : leaderboardByClan.values())
		{
			all.addAll(l);
		}
		return all;
	}

	@Override
	public void leaderboardSubmit(String name, String clan, long daily, long weekly)
	{
		ScheduledExecutorService e = exec;
		if (e == null || name == null || clan == null)
		{
			return;
		}
		e.execute(() -> sendResult("POST", "/leaderboard/submit",
				form("name", name, "clan", clan, "daily", Long.toString(daily), "weekly", Long.toString(weekly))));
	}

	@Override
	public void leaderboardAdd(String name, String clan, long dailyDelta, long weeklyDelta)
	{
		ScheduledExecutorService e = exec;
		if (e == null || name == null || clan == null)
		{
			return;
		}
		if (dailyDelta <= 0 && weeklyDelta <= 0)
		{
			return; // nothing to add (e.g. a seed from a fresh install with zero local totals)
		}
		e.execute(() -> sendResult("POST", "/leaderboard/add",
				form("name", name, "clan", clan,
						"daily", Long.toString(Math.max(0, dailyDelta)),
						"weekly", Long.toString(Math.max(0, weeklyDelta)))));
	}

	@Override
	public void leaderboardOptOut(String name)
	{
		ScheduledExecutorService e = exec;
		if (e == null || name == null)
		{
			return;
		}
		e.execute(() -> sendResult("POST", "/leaderboard/optout", form("name", name)));
	}

	@Override
	public void refreshLeaderboard()
	{
		ScheduledExecutorService e = exec;
		if (e != null)
		{
			e.execute(this::pollLeaderboard);
		}
	}

	@Override
	public AllianceTag allianceTagForPlayer(String playerName)
	{
		if (playerName == null)
		{
			return null;
		}
		String id = roster.get(playerName.toLowerCase());
		if (id == null)
		{
			return null;
		}
		String hex = allyColorById.get(id);
		if (hex == null)
		{
			return null; // alliance disbanded/unknown - show no badge rather than a wrong one
		}
		Integer icon = allyIconById.get(id);
		return new AllianceTag(hex, icon == null ? 0 : icon, id);
	}

	@Override
	public String allianceIdByDisplay(String display)
	{
		if (display == null)
		{
			return null;
		}
		for (Map.Entry<String, String> e : allyNameById.entrySet())
		{
			if (display.equalsIgnoreCase(e.getValue()) || display.equals(e.getKey()))
			{
				return e.getKey();
			}
		}
		return null;
	}

	@Override
	public Map<String, String> allianceColors()
